#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    int n, k;
    scanf("%d %d", &n, &k);
    // Min-heap keyed by (height, index).
    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<>> heap;
    for (int i = 0; i < k; i++) heap.push({0, i});
    vector<ll> h(k, 0);
    string out;
    for (int t = 0; t < n; t++) {
        ll pin;
        scanf("%lld", &pin);
        auto [cur, i] = heap.top(); heap.pop();
        if (t) out += ' ';
        out += to_string(i);
        h[i] = cur + pin;
        heap.push({h[i], i});
    }
    out += '\n';
    for (int i = 0; i < k; i++) { if (i) out += ' '; out += to_string(h[i]); }
    puts(out.c_str());
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int bp;

    static long nextLong() {
        while (buf[bp] <= ' ') bp++;
        long r = 0;
        while (bp < buf.length && buf[bp] > ' ') r = r * 10 + (buf[bp++] - '0');
        return r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) nextLong(), k = (int) nextLong();
        long[] h = new long[k];
        // Min-heap keyed by (height, index).
        PriorityQueue<Integer> heap = new PriorityQueue<>((a, b) -> h[a] != h[b] ? Long.compare(h[a], h[b]) : Integer.compare(a, b));
        for (int i = 0; i < k; i++) heap.add(i);
        StringBuilder sb = new StringBuilder();
        for (int t = 0; t < n; t++) {
            long pin = nextLong();
            int i = heap.poll();
            if (t > 0) sb.append(' ');
            sb.append(i);
            h[i] += pin;
            heap.add(i);
        }
        sb.append('\n');
        for (int i = 0; i < k; i++) { if (i > 0) sb.append(' '); sb.append(h[i]); }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"container/heap"
	"os"
	"strconv"
)

// colHeap is a min-heap of column indices keyed by (height, index).
type colHeap struct {
	idx []int
	h   []int64
}

func (c colHeap) Len() int { return len(c.idx) }
func (c colHeap) Less(i, j int) bool {
	a, b := c.idx[i], c.idx[j]
	if c.h[a] != c.h[b] {
		return c.h[a] < c.h[b]
	}
	return a < b
}
func (c colHeap) Swap(i, j int)  { c.idx[i], c.idx[j] = c.idx[j], c.idx[i] }
func (c *colHeap) Push(x any)    { c.idx = append(c.idx, x.(int)) }
func (c *colHeap) Pop() any      { x := c.idx[len(c.idx)-1]; c.idx = c.idx[:len(c.idx)-1]; return x }

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() int64 { sc.Scan(); v, _ := strconv.ParseInt(sc.Text(), 10, 64); return v }
	n, k := int(next()), int(next())
	ch := &colHeap{idx: make([]int, k), h: make([]int64, k)}
	for i := range ch.idx {
		ch.idx[i] = i
	}
	w := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer w.Flush()
	for t := 0; t < n; t++ {
		pin := next()
		i := ch.idx[0]
		ch.h[i] += pin
		heap.Fix(ch, 0)
		if t > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.Itoa(i))
	}
	w.WriteByte('\n')
	for i, v := range ch.h {
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.FormatInt(v, 10))
	}
	w.WriteByte('\n')
}
